import React from "react";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import QMoiKernelPanel from "./QMoiKernelPanel";
import { server } from "../../mocks/server";

// MSW setup is handled in src/setupTests.ts

describe("QMoiKernelPanel Integration", () => {
  beforeAll(async () => {
    // Ensure server is listening (use default onUnhandledRequest behavior)
    try {
      server.listen();
    } catch (e) {
      // already listening is fine
    }

    // Register local handlers explicitly to avoid relying on global setup timing
    const msw = await import("msw");
    // eslint-disable-next-line no-console
    console.log("TEST: msw keys:", Object.keys(msw));

    if ((msw as any).rest) {
      server.use(
        (msw as any).rest.get("/api/qmoi/status", (req: any, res: any, ctx: any) =>
          res(
            ctx.status(200),
            ctx.json({
              status: "OK",
              last_check: "2024-06-01T12:00:00Z",
              mutation_count: 5,
              logs: ["Log 1", "Log 2"],
            })
          )
        ),
        (msw as any).rest.post("/api/qmoi/payload", (req: any, res: any, ctx: any) => {
          const action = req.url.searchParams.get("qfix")
            ? "QFix"
            : req.url.searchParams.get("qoptimize")
            ? "QOptimize"
            : req.url.searchParams.get("qsecure")
            ? "QSecure"
            : "Unknown";
          return res(ctx.status(200), ctx.json({ message: `${action} done` }));
        })
      );
    } else if ((msw as any).http) {
      server.use(
        (msw as any).http.get("/api/qmoi/status", (req: any, res: any, ctx: any) =>
          res(
            ctx.status(200),
            ctx.json({
              status: "OK",
              last_check: "2024-06-01T12:00:00Z",
              mutation_count: 5,
              logs: ["Log 1", "Log 2"],
            })
          )
        ),
        (msw as any).http.post("/api/qmoi/payload", (req: any, res: any, ctx: any) => {
          const action = req.url.searchParams.get("qfix")
            ? "QFix"
            : req.url.searchParams.get("qoptimize")
            ? "QOptimize"
            : req.url.searchParams.get("qsecure")
            ? "QSecure"
            : "Unknown";
          return res(ctx.status(200), ctx.json({ message: `${action} done` }));
        })
      );
    } else {
      // Fallback: mock fetch directly if MSW helpers unavailable
      // eslint-disable-next-line no-console
      console.warn('TEST: msw has no rest/http helpers; mocking fetch directly');
      jest.spyOn(global, 'fetch' as any).mockImplementation(async (input: any) => {
        const url = typeof input === 'string' ? input : input.url;
        if (url.endsWith('/api/qmoi/status')) {
          return new Response(JSON.stringify({ status: 'OK', last_check: '2024-06-01T12:00:00Z', mutation_count: 5, logs: ['Log 1', 'Log 2']}), { status: 200 });
        }
        if (url.includes('/api/qmoi/payload')) {
          return new Response(JSON.stringify({ message: 'QFix done' }), { status: 200 });
        }
        return Promise.reject(new Error('Unexpected fetch in test'));
      });
    }
  });
  it("fetches and displays status from API", async () => {
    // Default MSW handlers (registered in test setup) provide the mocked status
    render(<QMoiKernelPanel isMaster={true} />);
    expect(await screen.findByText("OK")).toBeInTheDocument();
    expect(screen.getByText("Log 1")).toBeInTheDocument();
    expect(screen.getByText("Log 2")).toBeInTheDocument();
  });

  it("runs QFix and updates last action", async () => {
    // Default MSW handlers handle POST /api/qmoi/payload and status GET
    render(<QMoiKernelPanel isMaster={true} />);
    // wait for initial status fetch to complete and UI to update
    await screen.findByText("OK");
    fireEvent.click(screen.getByRole("button", { name: /Run QFix/i }));
    await waitFor(() =>
      expect(screen.getByText(/Last Action:/)).toBeInTheDocument()
    );
    expect(screen.getByText("QFix done")).toBeInTheDocument();
  });

  it("handles API error gracefully", async () => {
    // Override status handler to simulate an error response
    const msw = await import("msw");
    server.use(
      (msw as any).http.get(
        "/api/qmoi/status",
        (req: any, res: any, ctx: any) => {
          return res(ctx.status(500));
        }
      )
    );
    render(<QMoiKernelPanel isMaster={true} />);
    await waitFor(() => expect(screen.getByText(/Error:/)).toBeInTheDocument());
  });
});
